const b = $input.first().json; const h = b.headers || {};
if (h['x-run-token'] !== '08a9f0a324b9f219da0cd5b41b3122a293d41d2ade0dde67') { throw new Error('bad token'); }
const body = b.body || {};
const ids = Object.keys(body.keys || {});
if (!body.project_id || ids.length === 0 || ids.length > 40) { throw new Error('bad payload'); }
return [{ json: { project_id: body.project_id, ids: ids.join(','), keys: body.keys, dry_run: !!body.dry_run } }];

const c = $('Check').first().json; const r = $input.first().json; const cur = (r.body && r.body.keys) || [];
const byId = {}; for (const k of cur) { byId[String(k.key_id)] = k; }
const out = []; const skipped = []; let count = 0;
for (const id of Object.keys(c.keys)) {
  const k = byId[id]; if (!k) { skipped.push({ id: id, reason: 'not found' }); continue; }
  if (k.is_archived) { skipped.push({ id: id, reason: 'archived' }); continue; }
  const curT = {}; for (const t of (k.translations || [])) { curT[t.language_iso] = t; }
  const trs = [];
  for (const lang of Object.keys(c.keys[id].tr)) {
    const t = curT[lang];
    if (!t) { skipped.push({ id: id, lang: lang, reason: 'lang missing' }); continue; }
    if (t.translation && String(t.translation).trim()) { skipped.push({ id: id, lang: lang, reason: 'not empty', by: t.modified_by_email }); continue; }
    trs.push({ language_iso: lang, translation: c.keys[id].tr[lang], is_unverified: true }); count++;
  }
  if (trs.length) { out.push({ key_id: Number(id), translations: trs }); }
}
return [{ json: { project_id: c.project_id, dry_run: c.dry_run, get_status: r.statusCode, count: count, skipped: skipped, body: { keys: out } } }];

const b = $('Build').first().json; const r = $input.first().json;
if (b.dry_run) { return [{ json: { dry_run: true, would_write: b.count, skipped: b.skipped, keys: b.body.keys.length } }]; }
const sent = {}; for (const k of b.body.keys) { for (const t of k.translations) { sent[k.key_id + '|' + t.language_iso] = t.translation; } }
let ok = 0; const mismatch = [];
for (const k of ((r.body && r.body.keys) || [])) { for (const t of (k.translations || [])) { const key = k.key_id + '|' + t.language_iso; if (key in sent) { if (t.translation === sent[key]) { ok++; } else { mismatch.push({ key: key, sent: sent[key], got: t.translation }); } } } }
return [{ json: { put_status: r.statusCode, sent: b.count, confirmed: ok, mismatch: mismatch.slice(0, 20), errors: (r.body && r.body.errors) || null, skipped: b.skipped } }];
